#include <bits/stdc++.h>
using namespace std;

int pos(const vector<char>& s, int a, int b, int c, int k) {
    int ret = 0;
    for (char x : s) {
        if (x == 'V') {
            if (a == 0) {
                if (k == 0) return ret;
                ret++;
            } else {
                a--;
            }
        } else if (x == 'K') {
            if (b == 0) {
                if (k == 1) return ret;
                ret++;
            } else {
                b--;
            }
        } else {
            if (c == 0) {
                if (k == 2) return ret;
                ret++;
            } else {
                c--;
            }
        }
    }
    return -1;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    string lineS;
    cin >> lineS;
    vector<char> s(lineS.begin(), lineS.end());

    int vTotal = 0, kTotal = 0, eTotal = 0;
    for (char c : s) {
        if (c == 'V') vTotal++;
        else if (c == 'K') kTotal++;
        else eTotal++;
    }

    vector<vector<vector<vector<int>>>> dp(3, vector<vector<vector<int>>>(n + 1, vector<vector<int>>(n + 1, vector<int>(n + 1, INT_MAX))));
    vector<vector<vector<vector<int>>>> poss(3, vector<vector<vector<int>>>(vTotal + 1, vector<vector<int>>(kTotal + 1, vector<int>(eTotal + 1, -1))));

    for (int l = 0; l < 3; l++) {
        for (int i = 0; i <= vTotal; i++) {
            for (int j = 0; j <= kTotal; j++) {
                for (int k_ = 0; k_ <= eTotal; k_++) {
                    poss[l][i][j][k_] = pos(s, i, j, k_, l);
                }
            }
        }
    }

    dp[2][0][0][0] = 0;

    for (int i = 0; i <= vTotal; i++) {
        for (int j = 0; j <= kTotal; j++) {
            for (int k_ = 0; k_ <= eTotal; k_++) {
                for (int l = 0; l < 3; l++) {
                    if (dp[l][i][j][k_] == INT_MAX) continue;
                    if (i + 1 <= vTotal && poss[0][i][j][k_] != -1) {
                        int v = poss[0][i][j][k_];
                        dp[0][i + 1][j][k_] = std::min(dp[0][i + 1][j][k_], dp[l][i][j][k_] + v);
                        dp[1][i + 1][j][k_] = std::min(dp[1][i + 1][j][k_], dp[l][i][j][k_] + v);
                        dp[2][i + 1][j][k_] = std::min(dp[2][i + 1][j][k_], dp[l][i][j][k_] + v);
                    }
                    if (j + 1 <= kTotal && poss[1][i][j][k_] != -1) {
                        int v = poss[1][i][j][k_];
                        dp[1][i][j + 1][k_] = std::min(dp[1][i][j + 1][k_], dp[l][i][j][k_] + v);
                        dp[2][i][j + 1][k_] = std::min(dp[2][i][j + 1][k_], dp[l][i][j][k_] + v);
                        dp[0][i][j + 1][k_] = std::min(dp[0][i][j + 1][k_], dp[l][i][j][k_] + v);
                    }
                    if (k_ + 1 <= eTotal && poss[2][i][j][k_] != -1) {
                        int v = poss[2][i][j][k_];
                        dp[2][i][j][k_ + 1] = std::min(dp[2][i][j][k_ + 1], dp[l][i][j][k_] + v);
                        dp[1][i][j][k_ + 1] = std::min(dp[1][i][j][k_ + 1], dp[l][i][j][k_] + v);
                        dp[0][i][j][k_ + 1] = std::min(dp[0][i][j][k_ + 1], dp[l][i][j][k_] + v);
                    }
                }
            }
        }
    }

    int answer = std::min({dp[0][vTotal][kTotal][eTotal], dp[1][vTotal][kTotal][eTotal], dp[2][vTotal][kTotal][eTotal]});
    cout << answer << "\n";

    return 0;
}

